      "厳罰化が抑止力として機能するかという実証的問いがあり、少年犯罪の減少傾向を踏まえると現行制度の有効性を支持する立場と、重大事件の社会的影響を重視して制度改革を求める立場が対置される",
      "「特定少年」制度という折衷案の評価として、中間カテゴリーの設置が問題を先送りしているという批判と、個別事案に応じた柔軟対応を可能にする点を評価する視点がある",
      "被害者保護・被害者参加制度の拡充と少年の更生機会確保のどちらを優先するかという価値的トレードオフの視点",
