      "立地適正化計画を策定済みの市区町村数は2023年度末時点で800を超えており、制度開始以降着実に増加しているが、居住誘導の実効性については課題が指摘されている",
      "公共交通の維持が困難な地域では自動車依存が高まり、交通弱者である高齢者の移動手段確保が社会問題化しており、コンパクトシティ構想と公共交通網整備の一体的推進が不可欠とされている",
      "温室効果ガス排出の観点では、都市のスプロール化は移動距離の増大を通じてCO2排出量を増加させるため、集約型都市構造への転換は脱炭素化目標とも整合する",
