      "技術者個人の創造性・判断力と組織・制度・標準化の関係という視点。イノベーションには個人の発想が重要だが、安全基準や規格への準拠との緊張関係をどう捉えるかという論点",
      "先端技術の恩恵が社会に均等に分配されるかという公平性・アクセシビリティの視点。地域格差・経済格差・技術リテラシー格差と工学的解決策の関係を論じる角度",
