      "地下構造探査には重力探査・地震波探査・電気探査など複数の物理的手法があり、それぞれ異なる物理量（密度・弾性波速度・比抵抗）を利用しているため手法の比較考察が論述に有効",
      "キルヒホッフの電流則（KCL）と電圧則（KVL）は1845年に定式化され、複雑な回路網の解析に不可欠な原理であり、直列・並列・ブリッジ回路などの性質を論じる際の基盤となる",
      "自由落下や単振り子・斜面実験などによるgの測定精度は測定回数の増加と統計処理（誤差伝播）によって向上し、論述では測定誤差の要因と改善策を具体的に示すことが求められる",
