      "法政大学はグローバル教育の一環としてUCバークレーやロンドン大学など世界約200大学・機関と協定を結んでおり、英文学科でも海外協定校への留学プログラムが整備されている",
      "異文化接触を経験した学習者は、メタ言語意識や批判的読解力が高まるという第二言語習得研究の知見が複数報告されており、海外経験と英語学・文学研究の親和性を論じる根拠になりうる",
      "2023年のブリティッシュ・カウンシル報告では、英語を公用語・準公用語とする国が世界で60か国以上に及び、英語が国際共通語として果たす役割の多様性が改めて注目されている",
      "日本学術振興会などが推進するリベラルアーツ教育の文脈では、文学・語学の専門性に加え異文化コンピテンシーを持つ人材の重要性が強調されており、英文学科での学びはその育成に直結する",
