      "社会福祉協議会は全市区町村に設置されており、住民参加型の地域福祉活動計画の策定・推進において中心的役割を担っている",
      "孤独・孤立対策推進法が2023年に施行され、地域における人と人とのつながりの再構築が国の政策課題として明確に位置づけられた",
