      "訪日外国人旅行者数は2023年に約2500万人規模まで回復し、円安による日本の割安感がインバウンド需要を後押しした要因の一つとされている",
      "実質賃金は物価上昇に賃金上昇が追いつかず、2023年を通じてほぼマイナス圏で推移し、家計の実質購買力の目減りが続いた",
