      "トップダウン（国・自治体・大企業が主導）対ボトムアップ（市民・コミュニティ・スタートアップが主導）という変革主体をめぐる視点。SFCの理念に照らせば、後者のシビックテック的発想と前者の組み合わせを論じると説得力が増す",
      "短期的効果と長期的持続可能性のトレードオフという視点。即効性のある解決策が長期的に別の問題を生む可能性（例：補助金依存・環境負荷の転嫁）を考慮することで議論に厚みが出る",
      "ローカル最適対グローバル最適という軸。日本国内の文脈に特化した解決策を提案するのか、国際的な連携や他国の事例を援用するのかによって、提案の射程と説得力が異なる",
