    suggestedStructure: "序論で資料から読み取れる問題の本質（表面的現象ではなく構造的原因）を一文で定義し、本論前半でその原因分析を多角的に展開しつつ本論後半で実現可能性と副作用を考慮した独創的解決策を具体的に提示し、結論で提案が社会全体にもたらす価値とSFCの学際的アプローチとの親和性を簡潔に示す流れが有効である。",
