      "情報環境と民主的意思形成：SNSによるフィルターバブルや偽情報が熟慮ある政治参加を妨げるという現代固有の問題を、表現の自由規制とのバランスとして論じる軸",
      "グローバル化と国民主権の空洞化：国際機関や多国籍企業の影響力拡大により国内民主的決定が実質的に制約される構造を、主権概念の再定義という観点から考察する軸",
