    suggestedStructure: "序論で民主主義が抱える現代的課題を一つ明確に提示し問いを立て、本論で法的制度の機能と限界を具体的根拠とともに分析したうえで課題への対応策を論じ、結論で民主主義の本質的価値に立ち返りながら自身の規範的見解を簡潔に示す。",
