      "2022年のロシア・ウクライナ戦争では国連総会が緊急特別会合を開き、ロシアの侵攻を非難する決議を141か国の賛成で採択し、国際社会の道徳的判断が示された",
      "功利主義的観点では戦争の帰結（犠牲者数・社会的損失）が評価基準となる一方、義務論的観点では行為そのものの動機や規範への合致が問われ、同じ戦争行為でも評価が分かれる",
      "日本国憲法第9条は戦争放棄と戦力不保持を明記しており、国家レベルで平和主義を制度化した世界的に希少な事例として道徳的議論の参照点となっている",
