      "欧州司法裁判所は2023年にメタ社に対しGDPR違反で約12億ユーロの制裁金を科し、データの越境移転とプライバシー保護の国際的緊張が顕在化した",
      "日本の特定秘密保護法（2014年施行）や共謀罪法（2017年施行）は、捜査当局の情報収集権限拡大とプライバシー権・通信の秘密との関係で継続的な議論を呼んでいる",
      "国連人権理事会は2023年にAIを用いた大量監視が国際人権法上の恣意的干渉に該当しうると報告しており、監視技術の合法性判断に比例原則の適用が求められている",
