      "文部科学省の調査によれば、大学入学共通テストの平均正答率・得点分布の偏りから、上位層と中位層の識別力の低下が受験関係者の間で問題視されており、思考力を問う問題形式への移行が段階的に進められている",
      "SFCでは入学後にプロジェクト科目・フィールドワーク・卒業研究を必修的に課す課題解決型カリキュラムを採用しており、入試段階でも小論文によって志願者の論理構成力と問題設定能力を評価する方針を一貫して維持している",
      "高校教育との接続という観点から、指定校推薦・総合型選抜の拡大が一方では多様な才能の発掘に寄与するとされる一方、高校間・地域間・家庭環境間での準備格差を拡大させるという公正性の問題が研究者や教育政策の場で繰り返し論点に上がっている",
