      "解剖体を用いた実習（系統解剖）は死体解剖保存法に基づき行われ、医学部・歯学部・看護学部等が対象となるが、身体への敬意と倫理的態度の涵養が実習の重要目標とされている",
      "IPE（専門職連携教育）は世界保健機関（WHO）が2010年に「フレームワーク行動勧告」を発表して以降、医療系大学のカリキュラムに組み込まれつつある",
