      "解剖実習という非日常体験が医療職志望者の倫理的感受性・死生観に与える影響を、身体への敬意という規範形成の文脈で考察する視点",
      "患者の自律尊重と医療者のパターナリズムの緊張関係を、ケアの受け手がふれられる側として持つ脆弱性と主体性の観点から再構成する視点",
