      "日本国憲法第96条の憲法改正手続きは各議院の総議員の3分の2以上の賛成と国民投票における過半数を要件とし、通常の多数決より加重された手続きで基本秩序の変更に歯止めをかけている。",
      "欧州人権裁判所は2022年から2023年にかけて複数の案件で締約国の議会多数決による立法を条約違反と認定しており、超国家的な人権審査機関が国内多数決を統制する実例として注目される。",
      "日本の衆議院選挙における小選挙区制では2021年総選挙で自民党が得票率48パーセント程度ながら小選挙区議席の約8割を獲得しており、多数決の集計方式自体が代表の歪みを生む制度的問題を示している。",
