      "少数者保護の根拠をどこに求めるかという視点。功利主義的根拠（長期的社会厚生の最大化）と権利論的根拠（個人の尊厳は多数決で剥奪できない）を比較することで論の深みが増す。",
      "選挙制度・意思決定方式の多様性という視点。単純多数決以外にコンセンサス方式・比例代表・スーパーマジョリティ要件など多数決の設計自体を問い直すことで、原理の限界を補完する制度論的議論が展開できる。",
