    suggestedStructure: "序論でCSRの定義と現代的背景（ESG投資拡大・SDGs）を簡潔に示し、本論前半で具体的な企業事例を挙げながらCSRの意義（企業価値向上・社会課題解決・信頼獲得）を論じ、本論後半でグリーンウォッシュ問題やサプライチェーン管理の困難さなど課題を批判的に検討し、結論でCSRの実効性を高めるために企業・政府・消費者それぞれに求められる役割についての自身の見解を示す。",
