      "日本のスタートアップ育成5か年計画（2022年策定）では、2027年度までにスタートアップへの投資額を10兆円規模に拡大する目標が掲げられており、イノベーション政策が国家戦略として位置づけられている",
      "マイケル・ポーターらが提唱したCSV（Creating Shared Value）の概念では、企業競争力の強化と社会的価値の創出を同時に達成する戦略が、長期的な持続可能な成長につながると論じられている",
      "内閣府の調査では日本企業の研究開発費は2021年度に約14兆円に上るが、そのうち社会課題解決に直結する分野への配分は依然として限定的であるという指摘がある",
