      "厚生労働省の調査では、ヤングケアラーと呼ばれる家族の介護を担う18歳未満の子どもが中学生の約5.7%、高校生の約4.1%に上ることが2021年の実態調査で明らかにされた",
      "障害者雇用促進法に基づく民間企業の実雇用率は2023年時点で2.33%と過去最高を更新した一方、法定雇用率2.3%をかろうじて超えた水準にとどまる",
      "孤独・孤立対策推進法が2024年に施行され、国として孤独・孤立を社会的排除の重大リスクと位置づけ対策を体系化する動きが始まっている",
