    argumentAngles: [
      "普遍主義対選別主義の対立：すべての人を対象とする普遍的な社会保障の拡充と、特に脆弱な層に集中的に支援を届ける選別的アプローチのどちらが包摂に有効かという視点",
      "「支援の受け手」から「参加の主体」へのパラダイム転換：当事者が政策決定に関与するコ・プロダクション（共同生産）や当事者参加の仕組みを組み込むことで包摂の質が変わるという視点",
      "経済的支援と関係性の再構築の二層構造：物質的な貧困解消だけでなく、孤立・無縁社会への対応として地域コミュニティや居場所機能を福祉政策に組み込む必要性という視点",
      "制度の縦割り問題と「断らない相談支援」：複合的困難を抱える人が制度の隙間に落ちないよう、分野横断的なワンストップ支援体制をどう設計するかという行政構造の視点",
      "社会的包摂と財政制約のトレードオフ：少子高齢化による財政圧迫の中でいかに包摂的政策を持続可能にするか、投資的福祉（予防・早期介入）の論理でコスト最適化を図るという視点",
    ],
    suggestedStructure: "序論では社会的排除の多面的な定義と日本における現状（貧困・孤立・差別など）を具体的データで示し問題提起する。本論では排除の構造的要因を分析した上で、制度的・地域コミュニティ的・参加促進的の三層から包摂政策のあり方を論じ、結論では縦割りを超えた包括的支援と当事者主体の理念を組み合わせた政策像を自分の立場として提示する。",
