      "内閣府の試算ではまん延防止等重点措置1回あたりのGDPへの影響は数千億円規模とされており、経済損失と感染抑制効果の比較衡量が政策立案の中心課題となっていた",
      "ワクチン接種証明のデジタル化など公衆衛生目的で収集された個人データについて、個人情報保護法は利用目的の特定と目的外利用の原則禁止を定めており、データ活用の法的制約となっている",
      "接触確認アプリCOCOAは設計上のバグや通知遅延の問題が2021年に判明し、収集したデータが想定通りに機能しなかった事例として公衆衛生データ活用の技術的・運用的リスクを示した",
      "オミクロン株流行期の国際比較では行動制限の強度と経済回復速度の関係が国ごとに異なり、社会文化的要因や医療インフラの差が政策効果を左右することが指摘されている",
