    argumentAngles: [
      "短期的な感染抑制と中長期的な経済・社会的損失のトレードオフをどのような時間軸と指標で評価すべきかという政策評価の軸",
      "集団の公衆衛生と個人の経済活動・自由の衝突において国家介入をどこまで正当化できるかという自由主義対共同体主義の軸",
      "データ活用がもたらす効率的な感染追跡・資源配分という便益と、プライバシー侵害・監視社会化・データの目的外転用というリスクのバランスという技術倫理の軸",
      "感染症対策の恩恵と負担が経済的弱者・エッセンシャルワーカー・中小事業者に不均等に分配されるという公平性・分配的正義の軸",
      "科学的知見の不確実性が高い状況での意思決定において専門家・政府・市民がそれぞれどのような役割を担うべきかというガバナンスと民主的正統性の軸",
    ],
    suggestedStructure: "問題Aでは感染症対策と経済活動の具体的なトレードオフ構造を示した上で両立を可能にする条件や政策手段を論じ、問題Bでは公衆衛生目的のデータ活用が生む副作用として目的外利用・プライバシー侵害・データ格差などを具体的事例を交えて挙げ、それらを防ぐための制度的・倫理的配慮を提案する形で結論をまとめるとよい。",
