      "パリ協定は産業革命前比1.5〜2度以内の気温上昇抑制を目標とするが、各国のNDCを積み上げても2030年時点で必要な排出削減量には大きなギャップが残るとUNEPの排出ギャップ報告書は指摘している",
      "先進国が歴史的に蓄積してきた累積CO2排出量は途上国を大幅に上回り、「共通だが差異ある責任（CBDR）」原則が国連気候交渉の基本枠組みとなっているが、拘束力ある義務配分は依然未解決である",
