      "アルヴァックスが提唱した集合的記憶の概念では、個人の記憶も社会集団に所属することで初めて想起・維持されると論じられており、純粋に私的な記憶は理論上存在しないとされる",
      "アスマンが提唱する「文化的記憶」と「コミュニカティブ記憶」の区別によれば、日常的な対話で継承される記憶は約3世代（80〜100年）で消滅し、その後は儀礼・テキスト・モニュメントを媒介とした文化的記憶へと変容するとされる",
      "戦争証言の収集・デジタルアーカイブ化の動きは世界各地で進んでおり、証言者の高齢化に伴う一次記憶の消滅危機が歴史認識の継承問題を社会的課題として浮上させている",
