    suggestedStructure: "序論でSNSの普及という現状とエコーチェンバーを含む主要問題を端的に定義し、本論では情報流通・社会的分断・メンタルヘルスなど具体的な観点からメリットとデメリットを対比しながら論じ、結論でリテラシー教育やプラットフォーム規制など自分なりの解決策・展望を示す構成が有効である。",
