    suggestedStructure: "序論で「子ども」と「大人」の定義基準が多様であること（法・経済・心理・社会）を提示して問題を設定し、本論では少なくとも二つの基準を比較しながら大学生の実態を論じ、結論では単純な二分法を超えて「自律性と責任の引き受け方」という独自の基準を提示することで、スポーツ科学を学ぶ自分自身の立場も絡めた主張に着地させる。",
