      "デジタル端末の普及に伴い、青少年が何もしない時間に耐えられなくなっているという調査報告が複数の国で相次いでおり、注意持続時間の短縮や自己内省の機会の減少が懸念されている",
      "哲学者ラース・スヴェンセンは著書『退屈の小さな哲学』において、退屈を意味の欠如への反応として捉え、退屈と向き合うことが自己の欲求や価値観を問い直す契機になると論じている",
      "燃え尽き症候群の研究では、過密なスケジュールと刺激過多が続いたアスリートが競技への意味を見失うケースが報告されており、意図的に退屈を許容する休息期間の設計が再活性化に有効とされる場合がある",
