      "スポーツや身体活動の文脈で、反復練習や長期的なトレーニングに必然的に伴う退屈をどう意味づけるかという問いを通じて、忍耐や内発的動機の本質に迫ることができる",
      "退屈を社会的・文化的産物として見る視点、すなわち近代以降の余暇概念の成立とともに退屈が生まれたという歴史的文脈から、退屈の意味を相対化することができる",
      "退屈に対する個人の対処行動（逃避か受容か）が、その後の行動選択や人格形成にどのように影響するかという視点から、退屈を自己成長の試金石として論じることができる",
