      "テニスのグランドスラムではドロー（組み合わせ）によって上位シードの選手でも準々決勝前に激突する場合があり、組み合わせ抽選という運的要素が最終結果に影響を与えることはスポーツ統計学の文脈で繰り返し指摘されている",
      "2024年パリ五輪では複数競技でビデオ判定技術が導入・拡充されたが、それでも誤審や接触判定のグレーゾーンは完全には排除されず、判定という運的要因が競技結果に影響した事例が報告された",
      "心理学の研究では、自らの成功を運に帰属しすぎる選手は自己効力感が低下しやすい一方、失敗を運に帰属することで精神的回復が早まる場合もあるという帰属理論（attribution theory）の知見がスポーツ心理学に応用されている",
      "野球のセイバーメトリクス指標BABIP（フェアゾーンに飛んだ打球が安打になる割合）は長期的にはほぼ一定に収束するとされ、短期的な成績の変動には運の要素が含まれることを示す代表的データとして引用される",
